```js
let stale = false;
window.onNativeState = () => {
  // Activité en arrière-plan : on redessinera au retour
  if (document.hidden) { stale = true; return; }
  stale = false;
  const next = readState();
  if (!next) return;
  S = next;
  render();
};
document.addEventListener('visibilitychange', () => {
  if (!document.hidden && stale) window.onNativeState();
});
```
This turns the 30 s interval and background pushes into no-ops.
